function token() {
		$t = get_transient( 'ps_gsc_token' );
		if ( $t ) { return $t; }
		$sa = self::sa();
		if ( ! $sa ) { return new WP_Error( 'sa', 'ps_gsc_sa nėra' ); }
		$b64 = function ( $s ) { return rtrim( strtr( base64_encode( $s ), '+/', '-_' ), '=' ); };
		$now = time();
		$h   = $b64( json_encode( array( 'alg' => 'RS256', 'typ' => 'JWT' ) ) );
		$c   = $b64( json_encode( array( 'iss' => $sa['client_email'], 'scope' => 'https://www.googleapis.com/auth/webmasters.readonly',
			'aud' => $sa['token_uri'], 'exp' => $now + 3600, 'iat' => $now ) ) );
		$sig = '';
		if ( ! openssl_sign( $h . '.' . $c, $sig, $sa['private_key'], OPENSSL_ALGO_SHA256 ) ) { return new WP_Error( 'sign', 'openssl_sign nepavyko' ); }
		$r = wp_remote_post( $sa['token_uri'], array( 'timeout' => 20, 'body' => array(
			'grant_type' => 'urn:ietf:params:oauth:grant-type:jwt-bearer', 'assertion' => $h . '.' . $c . '.' . $b64( $sig ) ) ) );
		if ( is_wp_error( $r ) ) { return $r; }
		$j = json_decode( wp_remote_retrieve_body( $r ), true );
		if ( empty( $j['access_token'] ) ) { return new WP_Error( 'token', substr( wp_remote_retrieve_body( $r ), 0, 200 ) ); }
		set_transient( 'ps_gsc_token', $j['access_token'], 50 * MINUTE_IN_SECONDS );
		return $j['access_token'];
	}

